"""把接口用例转换为固定模板的 pytest + httpx 项目。"""
from __future__ import annotations

import json
from collections.abc import Iterable

from app.core.utils import now_iso
from app.repository import Repository
from app.schemas.api_testing import ApiCaseSpec, ApiSpec
from app.schemas.execution import AutomationArtifact, GeneratedFile

TEMPLATE_VERSION = "1.0.0"

_CONFTEST = '''\
"""Generated by Testing Assistant Platform v2.3. No secrets are stored here."""
import re
from collections.abc import Iterator
import os

import httpx
import pytest

PLACEHOLDER = re.compile(r"\\{\\{([A-Za-z_][A-Za-z0-9_]*)}}")


def resolve(value, env):
    if isinstance(value, str):
        return PLACEHOLDER.sub(
            lambda match: (
                env.get(match.group(1))
                or env.get(match.group(1).upper())
                or env.get(match.group(1).lower())
                or ""
            ),
            value,
        )
    if isinstance(value, list):
        return [resolve(item, env) for item in value]
    if isinstance(value, dict):
        return {key: resolve(item, env) for key, item in value.items()}
    return value


@pytest.fixture(scope="session")
def api_env():
    return os.environ


@pytest.fixture(scope="session")
def http_client():
    with httpx.Client(timeout=30.0, follow_redirects=True) as client:
        yield client
'''

_TEST_FILE = '''\
"""Generated contract tests. Business cases are data, not generated Python."""
import json
import re
from pathlib import Path

import pytest

from conftest import resolve

CASES = json.loads((Path(__file__).parents[1] / "cases.json").read_text(encoding="utf-8"))


def values_at_path(payload, path):
    if path in ("", "$"):
        return [payload]
    tokens = re.findall(r"[^.\\[\\]]+|\\[(?:\\*|\\d+)\\]", path.removeprefix("$"))
    values = [payload]
    for token in tokens:
        next_values = []
        if token == "[*]":
            for value in values:
                next_values.extend(value if isinstance(value, list) else [])
        elif token.startswith("[") and token.endswith("]"):
            index = int(token[1:-1])
            next_values.extend(value[index] for value in values if isinstance(value, list) and index < len(value))
        else:
            name = token.removeprefix(".")
            for value in values:
                if isinstance(value, dict) and name in value:
                    next_values.append(value[name])
                elif isinstance(value, list):
                    next_values.extend(
                        entry[name] for entry in value if isinstance(entry, dict) and name in entry
                    )
        values = next_values
    return values


@pytest.mark.parametrize("case", CASES, ids=[item["case_id"] for item in CASES])
def test_api_case(case, http_client, api_env):
    execution = resolve(case["execution"], api_env)
    headers = execution.get("headers") or {}
    params = execution.get("query") or {}
    cookies = execution.get("cookies") or {}
    kwargs = {"headers": headers, "params": params}
    if cookies:
        kwargs["cookies"] = cookies
    if execution.get("body") is not None:
        if execution.get("body_kind") == "json":
            kwargs["json"] = execution["body"]
        else:
            kwargs["content"] = str(execution["body"])
    response = http_client.request(
        execution["method"],
        execution["url"],
        **kwargs,
    )

    for assertion in case.get("assertions", []):
        if assertion.get("status") != "defined":
            continue
        kind = assertion.get("kind")
        expected = assertion.get("expected")
        if kind == "status":
            assert response.status_code == int(expected), (
                f"{case['case_id']}: expected status {expected}, got {response.status_code}"
            )
        elif kind == "header":
            actual = response.headers.get(str(assertion.get("path", "")))
            assert actual is not None, f"{case['case_id']}: missing header"
            operator = assertion.get("operator")
            if operator == "equals":
                assert actual == str(expected)
        elif kind == "json":
            actual_values = values_at_path(response.json(), str(assertion.get("path", "$")))
            operator = assertion.get("operator")
            if operator == "equals":
                if isinstance(expected, list):
                    assert actual_values == expected
                else:
                    assert actual_values == [expected]
            elif operator == "exists":
                assert actual_values and all(value is not None for value in actual_values)
            elif operator == "type":
                expected_type = str(expected)
                checks = {
                    "string": lambda value: isinstance(value, str),
                    "integer": lambda value: isinstance(value, int) and not isinstance(value, bool),
                    "number": lambda value: isinstance(value, (int, float)) and not isinstance(value, bool),
                    "boolean": lambda value: isinstance(value, bool),
                    "array": lambda value: isinstance(value, list),
                    "object": lambda value: isinstance(value, dict),
                    "null": lambda value: value is None,
                }
                check = checks.get(expected_type)
                assert actual_values and all(check is None or check(value) for value in actual_values), (
                    f"{case['case_id']}: {actual_values!r} is not {expected_type}"
                )
            elif operator == "in":
                assert actual_values and all(value in (expected or []) for value in actual_values)
            elif operator == "minLength":
                assert actual_values and all(len(str(value)) >= int(expected) for value in actual_values)
            elif operator == "maxLength":
                assert actual_values and all(len(str(value)) <= int(expected) for value in actual_values)
            elif operator == "gte":
                assert actual_values and all(value >= expected for value in actual_values)
            elif operator == "lte":
                assert actual_values and all(value <= expected for value in actual_values)
'''

_PYTEST_INI = """\
[pytest]
addopts = -ra
markers =
    api_contract: generated API contract case
"""

_REQUIREMENTS = """\
httpx>=0.27.0
pytest>=8.0.0
"""

_README = """\
# Generated API automation artifact

Generated by Testing Assistant Platform v2.3.1.

1. Create a virtual environment and install `requirements.txt`.
2. Copy `.env.example` to your own environment file and fill target values locally.
3. Run `pytest --junitxml=result.xml`.
4. Upload `result.xml` to the platform execution workspace.

The platform never executes this downloaded project and never stores credentials in it.
"""


def _case_payload(case: ApiCaseSpec) -> dict:
    return {
        "case_id": case.case_id,
        "title": case.title,
        "operation_id": case.operation_id,
        "category": case.category,
        "execution": case.execution.model_dump(mode="json"),
        "assertions": [item.model_dump(mode="json") for item in case.assertions],
    }


def _environment_names(cases: Iterable[ApiCaseSpec]) -> list[tuple[str, str, bool]]:
    found: dict[str, tuple[str, str, bool]] = {
        "baseUrl": ("baseUrl", "Target API base URL", False)
    }
    for case in cases:
        for item in case.execution.environment_variables:
            name = str(item.get("name") or "").strip()
            if not name:
                continue
            found[name] = (
                name,
                str(item.get("description") or "Generated environment variable"),
                bool(item.get("secret")),
            )
    return list(found.values())


def build_pytest_artifact(
    spec: ApiSpec,
    cases: list[ApiCaseSpec],
    *,
    artifact_id: str,
    revision: int,
) -> AutomationArtifact:
    """只通过固定模板拼装文件；case 内容始终以 JSON 数据承载。"""
    payload = json.dumps(
        [_case_payload(item) for item in cases],
        ensure_ascii=False,
        indent=2,
    )
    env_lines = [
        "# Fill values locally. Never commit real credentials.",
        *(f"{name}=" for name, _description, _secret in _environment_names(cases)),
        "",
    ]
    for name, description, secret in _environment_names(cases):
        env_lines.insert(
            max(len(env_lines) - 1, 0),
            f"# {name}: {description}{' (secret)' if secret else ''}",
        )
    files = [
        GeneratedFile(path="README.md", content=_README, media_type="text/markdown"),
        GeneratedFile(path="pytest.ini", content=_PYTEST_INI),
        GeneratedFile(
            path="requirements.txt",
            content=_REQUIREMENTS,
            media_type="text/plain",
        ),
        GeneratedFile(path=".env.example", content="\n".join(env_lines)),
        GeneratedFile(path="conftest.py", content=_CONFTEST, media_type="text/x-python"),
        GeneratedFile(path="cases.json", content=payload, media_type="application/json"),
        GeneratedFile(
            path="tests/test_api_cases.py",
            content=_TEST_FILE,
            media_type="text/x-python",
        ),
    ]
    return AutomationArtifact(
        artifact_id=artifact_id,
        spec_id=spec.spec_id,
        spec_title=spec.title,
        revision=revision,
        template_version=TEMPLATE_VERSION,
        case_ids=[item.case_id for item in cases],
        operation_ids=list(dict.fromkeys(item.operation_id for item in cases)),
        files=files,
        warnings=[] if cases else ["未选择任何接口用例，生成资产为空。"],
        created_at=now_iso(),
    )


__all__ = ["TEMPLATE_VERSION", "build_pytest_artifact"]
